import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { readdir, readFile, writeFile, mkdir, lstat, mkdtemp, rm, rename } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = process.cwd();
export const REPOSITORY = "https://github.com/covel-ai/covel-catalog";
const LEGACY_REPOSITORY = "https://github.com/covel-ai/covel-plugins";
const UPSTREAM_PATH = "packages/catalog-kit";
const digest = (bytes) => createHash("sha256").update(bytes).digest("hex");
const git = (source, args) => execFileSync("git", ["-C", source, ...args], { maxBuffer: 32 * 1024 * 1024 });

async function filesIn(directory, relative = "") {
  const result = [];
  for (const name of (await readdir(path.join(directory, relative))).sort()) {
    const filename = path.join(relative, name);
    const stat = await lstat(path.join(directory, filename));
    if (stat.isSymbolicLink()) throw new Error(`Linked file in catalog kit: ${filename}`);
    if (stat.isDirectory()) result.push(...await filesIn(directory, filename));
    else if (stat.isFile()) result.push(filename.split(path.sep).join("/"));
    else throw new Error(`Unexpected catalog kit file: ${filename}`);
  }
  return result.sort();
}

export async function checkKit(directory = root, { repository = REPOSITORY } = {}) {
  const lock = JSON.parse(await readFile(path.join(directory, "catalog-kit.lock.json"), "utf8"));
  if (lock.schemaVersion !== 1 || lock.repository !== repository || lock.upstreamPath !== UPSTREAM_PATH || !/^[a-f0-9]{40}$/.test(lock.commit)) throw new Error("Invalid catalog kit provenance");
  const target = path.join(directory, "vendor/catalog-kit");
  if (!(await lstat(target)).isDirectory() || (await lstat(target)).isSymbolicLink()) throw new Error("Linked or invalid catalog kit directory");
  const files = await filesIn(target);
  if (JSON.stringify(files) !== JSON.stringify(Object.keys(lock.files).sort())) throw new Error("Catalog kit has missing or extra files; use the fixed-commit sync command");
  for (const filename of files) if (digest(await readFile(path.join(target, filename))) !== lock.files[filename]) throw new Error(`Catalog kit modified: ${filename}`);
  const pkg = JSON.parse(await readFile(path.join(target, "package.json"), "utf8"));
  if (pkg.version !== lock.kitVersion) throw new Error("Catalog kit version differs from the source lock");
  return lock;
}

export async function syncKit({ commit, source, directory = root, migrateFromPlugins = false }) {
  if (!/^[a-f0-9]{40}$/.test(commit ?? "")) throw new Error("Sync requires a full fixed commit SHA");
  if (!source) {
    source = path.join(directory, ".cache/kit-upstream.git");
    await mkdir(source, { recursive: true });
    git(source, ["init", "--bare"]);
    git(source, ["fetch", "--depth=1", REPOSITORY, commit]);
  }
  const resolved = git(source, ["rev-parse", `${commit}^{commit}`]).toString().trim();
  if (resolved !== commit) throw new Error("Upstream commit did not resolve exactly");
  const records = git(source, ["ls-tree", "-rz", commit, "--", UPSTREAM_PATH]).toString().split("\0").filter(Boolean);
  if (!records.length) throw new Error("Upstream commit contains no catalog kit");
  const target = path.join(directory, "vendor/catalog-kit");
  await mkdir(path.dirname(target), { recursive: true });
  const staging = await mkdtemp(path.join(path.dirname(target), ".catalog-kit-sync-"));
  const files = {};
  try {
    for (const record of records) {
      const match = /^(100644|100755) blob ([a-f0-9]{40})\t(.+)$/.exec(record);
      if (!match) throw new Error("Upstream kit includes a linked or unsupported Git object");
      const [, mode, blob, fullPath] = match;
      const relative = fullPath.slice(`${UPSTREAM_PATH}/`.length);
      if (!fullPath.startsWith(`${UPSTREAM_PATH}/`) || relative.split("/").some((part) => !part || part === "." || part === "..") || relative.includes("\\")) throw new Error("Unsafe upstream kit path");
      const bytes = git(source, ["cat-file", "blob", blob]);
      const filename = path.join(staging, relative);
      await mkdir(path.dirname(filename), { recursive: true });
      await writeFile(filename, bytes, { mode: mode === "100755" ? 0o755 : 0o644 });
      files[relative] = digest(bytes);
    }
    const pkg = JSON.parse(await readFile(path.join(staging, "package.json"), "utf8"));
    const lock = { schemaVersion: 1, repository: REPOSITORY, upstreamPath: UPSTREAM_PATH, commit, kitVersion: pkg.version, files };
    try { await readFile(path.join(directory, "catalog-kit.lock.json")); await checkKit(directory, { repository: migrateFromPlugins ? LEGACY_REPOSITORY : REPOSITORY }); }
    catch (error) { if (error.code !== "ENOENT") throw error; }
    // This path is wholly generated by this tool; source code is never edited here.
    await mkdir(path.dirname(target), { recursive: true });
    await rm(target, { recursive: true, force: true });
    await rename(staging, target);
    await writeFile(path.join(directory, "catalog-kit.lock.json"), `${JSON.stringify(lock, null, 2)}\n`);
    return checkKit(directory);
  } finally { await rm(staging, { recursive: true, force: true }); }
}

export async function kitCli(args = process.argv.slice(2), directory = root) {
  const [command, ...valuesArgs] = args;
  args = valuesArgs;
  if (command === "check" && !args.length) {
    const lock = await checkKit(directory);
    console.log(`Catalog kit ${lock.kitVersion} verified at ${lock.commit}`);
  } else if (command === "sync") {
    const values = { directory };
    for (let i = 0; i < args.length; i += 2) {
      if (args[i] === "--migrate-from-plugins") { values.migrateFromPlugins = true; i--; continue; }
      if (!["--commit", "--source"].includes(args[i]) || !args[i + 1]) throw new Error("Expected --commit <SHA> [--source <checkout>]");
      values[args[i].slice(2)] = args[i + 1];
    }
    const lock = await syncKit(values);
    console.log(`Synced catalog kit ${lock.kitVersion} from ${lock.commit}`);
  } else throw new Error("Usage: node scripts/catalog-kit.mjs check | sync --commit <SHA> [--source <checkout>]");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) await kitCli();
